export class Order {
  readonly #lines: Line[] = [];
  #status: OrderStatus = 'new';

  addLine(line: Line): void {
    if (this.#status !== 'new') throw new Error('order closed');
    this.#lines.push(line);
  }
  get total(): Money { return sum(this.#lines); }
}

