// order.ts
export interface Order { readonly lines: readonly Line[]; readonly status: 'new' | 'paid' }
export const openOrder = (): Order => ({ lines: [], status: 'new' });
export const addLine = (o: Order, line: Line): Order =>
  o.status !== 'new' ? o : { ...o, lines: [...o.lines, line] };
export const total = (o: Order): Money => sum(o.lines);
